pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        uint256 before;
        try c.currentBetLimit() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.AdjustBetAmounts(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ? c.currentBetLimit() == before : c.currentBetLimit() == amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
